#include "oldbox/keymap.hpp"

namespace oldbox {
namespace {

// PC/AT set-1 make codes for the SDL3 scancodes used by PC keyboards.
// Keys without a plain make code (PrintScreen, Pause, media/system keys) stay
// zero: sending their base byte would be interpreted as a different key
// (KP *, NumLock).
// The E0 prefix is generated by Keyboard::key_event() for extended keys.
struct Entry { int sdl; u8 code; bool extended; };
constexpr Entry kEntries[] = {
    // Letters.
    {4, 0x1E, false}, {5, 0x30, false}, {6, 0x2E, false},
    {7, 0x20, false}, {8, 0x12, false}, {9, 0x21, false},
    {10, 0x22, false}, {11, 0x23, false}, {12, 0x17, false},
    {13, 0x24, false}, {14, 0x25, false}, {15, 0x26, false},
    {16, 0x32, false}, {17, 0x31, false}, {18, 0x18, false},
    {19, 0x19, false}, {20, 0x10, false}, {21, 0x13, false},
    {22, 0x1F, false}, {23, 0x14, false}, {24, 0x16, false},
    {25, 0x2F, false}, {26, 0x11, false}, {27, 0x2D, false},
    {28, 0x15, false}, {29, 0x2C, false},
    // Digits.
    {30, 0x02, false}, {31, 0x03, false}, {32, 0x04, false},
    {33, 0x05, false}, {34, 0x06, false}, {35, 0x07, false},
    {36, 0x08, false}, {37, 0x09, false}, {38, 0x0A, false},
    {39, 0x0B, false},
    // Control/punctuation.
    {40, 0x1C, false}, // Return
    {41, 0x01, false}, // Escape
    {42, 0x0E, false}, // Backspace
    {43, 0x0F, false}, // Tab
    {44, 0x39, false}, // Space
    {45, 0x0C, false}, // Minus
    {46, 0x0D, false}, // Equals
    {47, 0x1A, false}, // Left bracket
    {48, 0x1B, false}, // Right bracket
    {49, 0x2B, false}, // Backslash
    {50, 0x2B, false}, // Non-US hash (same physical position on ISO)
    {51, 0x27, false}, // Semicolon
    {52, 0x28, false}, // Apostrophe
    {53, 0x29, false}, // Grave
    {54, 0x33, false}, // Comma
    {55, 0x34, false}, // Period
    {56, 0x35, false}, // Slash
    {57, 0x3A, false}, // CapsLock
    // Function keys F1-F12.
    {58, 0x3B, false}, {59, 0x3C, false}, {60, 0x3D, false},
    {61, 0x3E, false}, {62, 0x3F, false}, {63, 0x40, false},
    {64, 0x41, false}, {65, 0x42, false}, {66, 0x43, false},
    {67, 0x44, false}, {68, 0x57, false}, {69, 0x58, false},
    // PrintScreen (70) and Pause (72) need E0/E1 sequences; unmapped.
    {71, 0x46, false}, // ScrollLock
    // Navigation cluster: E0-prefixed set-1 codes.
    {73, 0x52, true}, // Insert
    {74, 0x47, true}, // Home
    {75, 0x49, true}, // PageUp
    {76, 0x53, true}, // Delete
    {77, 0x4F, true}, // End
    {78, 0x51, true}, // PageDown
    {79, 0x4D, true}, // Right
    {80, 0x4B, true}, // Left
    {81, 0x50, true}, // Down
    {82, 0x48, true}, // Up
    // Keypad.
    {83, 0x45, false}, // NumLock
    {84, 0x35, true},  // KP divide (E0)
    {85, 0x37, false}, // KP multiply
    {86, 0x4A, false}, // KP minus
    {87, 0x4E, false}, // KP plus
    {88, 0x1C, true},  // KP Enter (E0)
    {89, 0x4F, false}, {90, 0x50, false}, {91, 0x51, false},
    {92, 0x4B, false}, {93, 0x4C, false}, {94, 0x4D, false},
    {95, 0x47, false}, {96, 0x48, false}, {97, 0x49, false},
    {98, 0x52, false}, {99, 0x53, false},
    // ISO extra key and Menu.
    {100, 0x56, false}, // Non-US backslash
    {101, 0x5D, true},  // Application/Menu (E0)
    {103, 0x59, false}, // KP equals
    // F13-F24.
    {104, 0x64, false}, {105, 0x65, false}, {106, 0x66, false},
    {107, 0x67, false}, {108, 0x68, false}, {109, 0x69, false},
    {110, 0x6A, false}, {111, 0x6B, false}, {112, 0x6C, false},
    {113, 0x6D, false}, {114, 0x6E, false}, {115, 0x6F, false},
    // Modifiers.  Right Ctrl/Alt are E0-prefixed; right Shift is not.
    {224, 0x1D, false}, // Left Ctrl
    {225, 0x2A, false}, // Left Shift
    {226, 0x38, false}, // Left Alt
    {227, 0x5B, true},  // Left GUI
    {228, 0x1D, true},  // Right Ctrl
    {229, 0x36, false}, // Right Shift
    {230, 0x38, true},  // Right Alt
    {231, 0x5C, true},  // Right GUI
};

} // namespace

Set1Key sdl_scancode_to_set1(int sdl_scancode) {
    for (const Entry& e : kEntries)
        if (e.sdl == sdl_scancode) return {e.code, e.extended};
    return {};
}

} // namespace oldbox
